using System.Diagnostics;using System.IO;using System.Text.Json;using System.Security.Cryptography;using System.Windows.Media;using System.Windows.Media.Imaging;using Kitao.InstantFilm.Research;using RAWSelectionAssistant.Core.Services.Color;using RAWSelectionAssistant.Core.Services.Projects;
if(args.Length!=2)throw new ArgumentException("reference binary directory / new output");var bins=Path.GetFullPath(args[0]);var output=Path.GetFullPath(args[1]);if(Directory.Exists(output))throw new IOException("New output");Directory.CreateDirectory(output);var rows=new List<object>();
(double[] Data,double Ms,long Peak) Run(string name,string input){var sw=Stopwatch.StartNew();using var p=Process.Start(new ProcessStartInfo(Path.Combine(bins,name+".exe")){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true})!;var textTask=p.StandardOutput.ReadToEndAsync();var errorTask=p.StandardError.ReadToEndAsync();long peak=0;try{p.Refresh();peak=p.PeakWorkingSet64;}catch(InvalidOperationException){}p.StandardInput.Write(input);p.StandardInput.Close();if(!p.WaitForExit(30000)){p.Kill(true);throw new TimeoutException("Reference worker");}var text=textTask.GetAwaiter().GetResult();var err=errorTask.GetAwaiter().GetResult();if(p.ExitCode!=0)throw new IOException(err);return(text.Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries).Select(x=>double.Parse(x,System.Globalization.CultureInfo.InvariantCulture)).ToArray(),sw.Elapsed.TotalMilliseconds,peak);}
var cases=new List<(string Name,int W,int H,float[] Pixels)>();const int w=37,h=33;
foreach(var kind in new[]{"gray","saturated","impulse","edge","flat","negative-overrange"}){var data=new float[w*h*3];for(int y=0;y<h;y++)for(int x=0;x<w;x++)for(int c=0;c<3;c++){float v=kind switch{"gray"=>x/(float)(w-1),"saturated"=>c==x%3?1:0,"impulse"=>x==18&&y==16?1:0,"edge"=>x<18?0:1,"flat"=>.18f,_=>x/(float)(w-1)*2.5f-.5f};data[(y*w+x)*3+c]=v;}cases.Add((kind,w,h,data));}
var manifest=JsonSerializer.Deserialize<JsonElement>(File.ReadAllText("N:/pixart/kitao-instant-film-evidence-v3-20261016/.validation/instant-v3/review-inputs.json"));foreach(var item in manifest.EnumerateArray()){string file=item.GetProperty("FrozenTiff").GetString()!;using(var f=File.OpenRead(file))if(Convert.ToHexString(SHA256.HashData(f))!=item.GetProperty("ExpectedFrozenSha256").GetString())throw new InvalidDataException("frozen identity");using var stream=File.OpenRead(file);var frame=BitmapDecoder.Create(stream,BitmapCreateOptions.PreservePixelFormat|BitmapCreateOptions.IgnoreColorProfile,BitmapCacheOption.OnDemand).Frames[0];var converted=new FormatConvertedBitmap(frame,PixelFormats.Rgb48,null,0);var center=new ushort[w*h*3];converted.CopyPixels(new System.Windows.Int32Rect(frame.PixelWidth/2,frame.PixelHeight/2,w,h),center,w*6,0);cases.Add((item.GetProperty("Id").GetString()!,w,h,center.Select(v=>v/65535f).ToArray()));}
foreach(var sample in cases){var invariant=System.Globalization.CultureInfo.InvariantCulture;string Numbers(IEnumerable<double> x)=>string.Join('\n',x.Select(v=>v.ToString("R",invariant)));var linear=sample.Pixels.Select(v=>CandidateTone.Decode(v)).ToArray();var dt=Run("darktable-exposure",Numbers(linear));var rt=Run("rawtherapee-basecurve",Numbers(linear));double maxExposure=dt.Data.Zip(linear).Max(pair=>Math.Abs(pair.First-2*pair.Second));if(maxExposure>2e-6)throw new InvalidDataException("Exposure behavior");var channel=linear.Where((_,i)=>i%3==0).ToArray();var input=$"{sample.W} {sample.H}\n"+Numbers(channel);var dg=Run("darktable-gaussian",input);var rg=Run("rawtherapee-gauss3",input);var coords=Enumerable.Range(0,w*h).Select(i=>$"{i%w/37d*11.37:R} {i/w/33d*9.11:R}");var dn=Run("darktable-grain-noise",string.Join('\n',coords));var sn=Run("stb-independent-noise",string.Join('\n',coords));var image=new HighBitDepthImageBuffer(w,h,sample.Pixels,"32f","sRGB",1);var watch=Stopwatch.StartNew();using var rendered=CandidateSpatial.RenderRegion(image,CandidateRecipe.Create("modern-itype-v3"),0,0,w,h);using var borrow=rendered.Borrow();var candidate=borrow.Image.Rgb32.ToArray();if(candidate.Any(x=>!float.IsFinite(x)||x<0||x>1))throw new InvalidDataException("candidate domain");
object Stats(double[] v){var mean=v.Average();double variance=v.Average(x=>(x-mean)*(x-mean));var spectrum=new List<double>();foreach(var k in new[]{1,3,8,15}){double re=0,im=0;for(int x=0;x<w;x++){re+=v[x]*Math.Cos(2*Math.PI*k*x/w);im-=v[x]*Math.Sin(2*Math.PI*k*x/w);}spectrum.Add((re*re+im*im)/w);}return new{mean,variance,rowDftPower=spectrum};}
rows.Add(new{sample=sample.Name,inputSha256=Convert.ToHexString(SHA256.HashData(System.Runtime.InteropServices.MemoryMarshal.AsBytes(sample.Pixels.AsSpan()))),domain="display sRGB clamp/EOTF -> linear reference exposure and filters; original creative tone not required identical",maxExposure,dtMs=dt.Ms,rtMs=rt.Ms,dtGaussianMs=dg.Ms,rtFiniteMs=rg.Ms,noiseMs=dn.Ms+sn.Ms,referencePeak=new[]{dt.Peak,rt.Peak,dg.Peak,rg.Peak,dn.Peak,sn.Peak}.Max(),candidateMs=watch.Elapsed.TotalMilliseconds,candidatePeak=Process.GetCurrentProcess().PeakWorkingSet64,filterMaximumDifference=dg.Data.Zip(rg.Data).Max(p=>Math.Abs(p.First-p.Second)),noiseDarktable=Stats(dn.Data),noiseStb=Stats(sn.Data),candidateStatistics=Stats(candidate.Select(v=>(double)v).ToArray()),acceptance="Domain finite/range, exposure2e-6, tile1e-6, flat1e-6, repeat exact; creative appearance has no equality threshold"});}
